#[test]
fn review_disable_server_with_pending_initial() {
    let mut pair = Pair::default();
    pair.server.handle_incoming = Box::new(|_| IncomingConnectionBehavior::Wait);
    pair.begin_connect(client_config());
    pair.drive_client();
    let retransmit = pair.server.inbound.front().unwrap().clone();
    pair.server.drive_incoming(pair.time, pair.client.addr);
    assert_eq!(pair.server.waiting_incoming.len(), 1);
    pair.server.set_server_config(None);
    // A duplicate of the original ordinary Initial can still arrive while the application decides.
    pair.server.inbound.push_back(retransmit);
    pair.server.drive_incoming(pair.time, pair.client.addr);
    let incoming = pair.server.waiting_incoming.pop().unwrap();
    pair.server.ignore(incoming);
}

#[test]
fn review_accept_pending_after_disabling_server() {
    let mut pair = Pair::default();
    pair.server.handle_incoming = Box::new(|_| IncomingConnectionBehavior::Wait);
    pair.begin_connect(client_config());
    pair.drive_client();
    pair.server.drive_incoming(pair.time, pair.client.addr);
    let incoming = pair.server.waiting_incoming.pop().unwrap();
    pair.server.set_server_config(None);
    pair.server.try_accept(incoming, pair.time).unwrap();
}

