#[cfg(test)]
mod review_tests {
    use super::*;
    use crate::{RecvStream, Side};
    use bytes::Bytes;

    fn state() -> StreamsState {
        StreamsState::new(Side::Client, 1u32.into(), 0u32.into(), 100, 100u32.into(), 100u32.into())
    }

    #[test]
    fn review_stopped_reset_credits_once() {
        let mut s = state();
        let id = StreamId::new(Side::Server, Dir::Uni, 0);
        let _ = s.received(frame::Stream { id, offset: 0, fin: false, data: Bytes::from_static(&[0; 32]) }, 32).unwrap();
        let mut pending = Retransmits::default();
        RecvStream { id, state: &mut s, pending: &mut pending }.stop(0u32.into()).unwrap();
        assert_eq!(s.local_max_data, 132);
        let _ = s.received_reset(frame::ResetStream { id, error_code: 0u32.into(), final_offset: 32u32.into() }).unwrap();
        assert_eq!(s.data_recvd, 32);
        assert_eq!(s.local_max_data, 132, "reset must not credit bytes already credited by stop");
    }

    #[test]
    fn review_receive_window_shrink_expand_does_not_add_credit() {
        let mut s = state();
        assert_eq!(s.local_max_data, 100);
        s.set_receive_window(50u32.into());
        s.set_receive_window(100u32.into());
        assert_eq!(s.local_max_data, 100, "restoring the original window before any reads should not advertise extra credit");
        assert_eq!(s.receive_window_shrink_debt, 0);
    }
}
