        for round in 2..22 {
            now += Duration::from_millis(10);
            s.on_sent(now, 1000);
            s.on_ack(now, now, 1000, round, false);
            s.end_acks(round, false);
        }
        assert_eq!(s.get_estimate(), 100_000, "the ten-round maximum filter must expire the old rate");
    }
}
